// src/pages/Resume.js
import React, { Suspense, useMemo, useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import './Resume.css';
import { lazyChunk, loadResumePdf, resetFailedPages } from '../pageLoaders';

/* react-pdf (pdf.js) draws the phone viewer only; it is a chunk of its own
   (ResumePdfPages.js), loaded once the page is in phone mode */
const PdfPages = lazyChunk(loadResumePdf);

/* If the viewer's code cannot load (offline), say so inside the viewer and
   offer a retry, so the document toggle and the Open / Download buttons
   stay usable instead of the whole page turning into an error */
class ViewerBoundary extends React.Component {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  retry = () => {
    resetFailedPages();
    this.setState({ failed: false });
  };
  render() {
    if (!this.state.failed) return this.props.children;
    return (
      <div className="page-load-error" role="alert">
        <p>The viewer could not load. Open and Download above still work.</p>
        <button type="button" onClick={this.retry}>Try again</button>
      </div>
    );
  }
}

export default function Resume() {
  const params = new URLSearchParams(window.location.search);
  const initial =
    params.get('doc') === 'diploma' || window.location.hash === '#diploma'
      ? 'diploma'
      : 'resume';

  const [doc, setDoc] = React.useState(initial);
  const location = useLocation();
  const [isPhone, setIsPhone] = useState(false);
  const [numPages, setNumPages] = useState(0);

  // Keep your links exactly as-is
  const files = useMemo(() => ({
    resume:  { label: 'Resume',  url: `${process.env.PUBLIC_URL}/HyderMohyuddin-Resume.pdf` },
    diploma: { label: 'Diploma', url: `${process.env.PUBLIC_URL}/HyderMohyuddin-Diploma.pdf` },
  }), []);
  const active = files[doc];

  // Phone-mode detection (width-based, no UA sniffing)
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 900px)');
    const update = () => setIsPhone(mq.matches);
    update();
    mq.addEventListener?.('change', update);
    return () => mq.removeEventListener?.('change', update);
  }, []);

  // Measure container width (for phone mode only)
  const wrapRef = useRef(null);
  const [pageWidth, setPageWidth] = useState(800);
  useEffect(() => {
    if (!isPhone) return;
    const el = wrapRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => {
      const w = Math.floor(entry.contentRect.width);
      setPageWidth(Math.max(320, Math.min(1200, w)));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [isPhone]);

  // Reset pages when switching docs (phone mode viewer)
  useEffect(() => { setNumPages(0); }, [doc]);

  /* Deep links: /resume#diploma opens the diploma directly (the chat's
     "diploma" phrase points here). Keyed on location because a react-router
     <Link> push does not fire hashchange; the listener covers hand-edited
     URLs. Explicit hashes only - an empty hash must NOT force 'resume', or
     the ?doc=diploma query path above would be clobbered on mount. Only
     setDoc happens here: no scrolling, no navigation, so ScrollToTop and
     the phone viewer's own reset machinery stay in charge. */
  useEffect(() => {
    const applyHash = () => {
      const h = window.location.hash;
      if (h === '#diploma') setDoc('diploma');
      else if (h === '#resume') setDoc('resume');
    };
    applyHash();
    window.addEventListener('hashchange', applyHash);
    return () => window.removeEventListener('hashchange', applyHash);
  }, [location]);

  // Open/download icon buttons for the CURRENT doc. Phone mode floats them
  // over the viewer; desktop puts them in the toggle row so they never
  // overlap the PDF plugin's own chrome (e.g. Firefox's pdf.js toolbar).
  const docActions = (bar) => (
    <div
      className={`pdf-actions${bar ? " pdf-actions--bar" : ""}`}
      role="group"
      aria-label="Current document actions"
    >
      <a
        className="icon-btn"
        href={active.url}
        target="_blank"
        rel="noopener noreferrer"
        aria-label={`Open ${active.label} in a new tab`}
        title={`Open ${active.label} in a new tab`}
      >
        {/* External-link icon (SVG, crisp on all screens) */}
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M14 3h7v7h-2V6.41l-9.29 9.3-1.42-1.42 9.3-9.29H14V3z"></path>
          <path d="M19 21H5a2 2 0 0 1-2-2V5c0-1.1.9-2 2-2h7v2H5v14h14v-7h2v7a2 2 0 0 1-2 2z"></path>
        </svg>
        <span className="sr-only">Open</span>
      </a>
      <a
        className="icon-btn"
        href={active.url}
        download
        aria-label={`Download ${active.label} PDF`}
        title={`Download ${active.label} PDF`}
      >
        {/* Download icon */}
        <svg viewBox="0 0 24 24" aria-hidden="true">
          <path d="M12 3v10.59l3.3-3.3 1.4 1.42-5 5-5-5 1.4-1.42 3.3 3.3V3h2z"></path>
          <path d="M5 19h14v2H5z"></path>
        </svg>
        <span className="sr-only">Download</span>
      </a>
    </div>
  );

  return (
    <div className="resume-pdf-wrapper">
      {/* Segmented control */}
      <div className="doc-toggle" role="tablist" aria-label="Document selector">
        {(['resume','diploma']).map(key => (
          <button
            key={key}
            role="tab"
            aria-selected={doc === key}
            aria-controls="pdf-viewer"
            className={`doc-toggle-btn ${doc === key ? 'active' : ''}`}
            onClick={() => setDoc(key)}
          >
            {files[key].label}
          </button>
        ))}
        {!isPhone && docActions(true)}
      </div>

      {/* Viewer */}
      {isPhone ? (
        // PHONE MODE: react-pdf (multi-page, mobile-safe)
        <div className="pdf-viewport">
          {docActions(false)}

          <div id="pdf-viewer" className="pdf-scroll" ref={wrapRef}>
            <ViewerBoundary>
              <Suspense fallback={<div className="pdf-loading">Loading…</div>}>
                <PdfPages url={active.url} numPages={numPages} onPages={setNumPages} pageWidth={pageWidth} />
              </Suspense>
            </ViewerBoundary>
          </div>
        </div>
      ) : (
        // NORMAL MODE: original <object> embed (actions live in the toggle row)
        <object
          id="pdf-viewer"
          data={`${active.url}#toolbar=0&navpanes=0&scrollbar=1`}
          type="application/pdf"
          className="resume-pdf-frame"
          aria-label={`${active.label} PDF`}
        >
          <p className="resume-fallback">
            Your device can’t display the PDF inline.&nbsp;
            <a href={active.url} target="_blank" rel="noopener noreferrer">Open</a>&nbsp;or&nbsp;
            <a href={active.url} download>download</a> the {active.label}.
          </p>
        </object>
      )}
    </div>
  );
}
